import { readFile, readdir, stat } from "node:fs/promises";
import path from "node:path";

import type { UploadedFile } from "@/ingest/load-upload";

/** Generated by `pnpm run samples`; committed so the demo works from a fresh clone. */
export const SAMPLES_DIR = path.join(process.cwd(), "data", "samples");

export async function listSampleFiles(): Promise<{ name: string; size: number }[]> {
  const names = (await readdir(SAMPLES_DIR)).filter((name) => /\.(pdf|csv)$/i.test(name)).sort();
  return Promise.all(names.map(async (name) => ({ name, size: (await stat(path.join(SAMPLES_DIR, name))).size })));
}

export async function readSampleFiles(): Promise<UploadedFile[]> {
  const files = await listSampleFiles();
  return Promise.all(files.map(async ({ name }) => ({ name, bytes: new Uint8Array(await readFile(path.join(SAMPLES_DIR, name))) })));
}
